```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
using namespace std;

bool samogloska(char c) {
    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
}

int main() {
    ifstream plik("napisy.txt");
    string s;
    vector<string> napisy;
    while (plik >> s) napisy.push_back(s);

    // a)
    cout << "a) Samogloski i spolgloski:" << endl;
    vector<int> vSam, vSpo;
    for (const string& n : napisy) {
        int sam = 0, spo = 0;
        for (char c : n) {
            if (samogloska(c)) sam++;
            else spo++;
        }
        vSam.push_back(sam);
        vSpo.push_back(spo);
        cout << n << ": samoglosek=" << sam << ", spolgloski=" << spo << endl;
    }

    // b)
    cout << endl << "b) Napisy z przewaga samoglosek:" << endl;
    int ile = 0;
    for (int i = 0; i < (int)napisy.size(); i++) {
        if (vSam[i] > vSpo[i]) {
            cout << napisy[i] << " (" << vSam[i] << " > " << vSpo[i] << ")" << endl;
            ile++;
        }
    }
    cout << "Ilosc: " << ile << endl;

    // c)
    cout << endl << "c) Najdluzszy ciag samoglosek:" << endl;
    int maxCiag = 0;
    string maxNapis;
    for (const string& n : napisy) {
        int best = 0, cur = 0;
        for (char c : n) {
            if (samogloska(c)) {
                cur++;
                if (cur > best) best = cur;
            } else {
                cur = 0;
            }
        }
        cout << n << ": najdluzszy ciag = " << best << endl;
        if (best > maxCiag) {
            maxCiag = best;
            maxNapis = n;
        }
    }
    cout << "Rekord: " << maxNapis << " (ciag " << maxCiag << " samoglosek)" << endl;
    return 0;
}
```

**Wyjasnienie**: Wieloetapowa analiza: (a) klasyfikacja znakow, (b) filtrowanie warunkowe, (c) algorytm "biezacego ciagu" z resettowaniem licznika.

